  path=[a,b]; seen.add(e); prev,a0=a,b
  while a0 not in crit:
   ns=[x for x in adj[a0] if x!=prev];
   if not ns:break
   nxt=ns[0]; seen.add(tuple(sorted((a0,nxt))));path.append(nxt);prev,a0=a0,nxt
  chains.append(path)
def rdp(P,eps=3):
 P=np.array(P,float)
 if len(P)<=2:return P.astype(int)
 a,b=P[0],P[-1]; d=b-a; n=np.linalg.norm(d)
 if n==0: dist=np.linalg.norm(P-a,axis=1)
 else: dist=np.abs(np.cross(d,P-a))/n
 i=int(np.argmax(dist))
 if dist[i]<=eps:return np.array([P[0],P[-1]],int)
 return np.vstack([rdp(P[:i+1],eps)[:-1],rdp(P[i:],eps)])
